<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
get_header(); the_post();
$episode_id=get_the_ID();$show_id=absint(get_post_meta($episode_id,'_nfinite_episode_show_id',true));$creator_id=absint(get_post_meta($episode_id,'_nfinite_episode_creator_id',true));if(!$creator_id&&$show_id){$creator_id=absint(get_post_meta($show_id,'_nfinite_show_creator_id',true));}$video=esc_url(get_post_meta($episode_id,'_nfinite_episode_video_url',true));$audio=esc_url(get_post_meta($episode_id,'_nfinite_episode_audio_url',true));$season=absint(get_post_meta($episode_id,'_nfinite_episode_season',true));$number=absint(get_post_meta($episode_id,'_nfinite_episode_number',true));$runtime=get_post_meta($episode_id,'_nfinite_episode_runtime',true);$guests=(array)get_post_meta($episode_id,'_nfinite_episode_guests',true);$embed=$video&&class_exists('Nfinite_Creators_Discovery_Hubs')?Nfinite_Creators_Discovery_Hubs::video_embed_url($video):'';
?>
<main class="nfinite-episode-single"><article><div class="nfinite-episode-single__meta"><?php if($show_id):?><a href="<?php echo esc_url(get_permalink($show_id));?>"><?php echo esc_html(get_the_title($show_id));?></a><?php endif;?><?php if($season||$number):?> <span><?php echo esc_html(trim(($season?'S'.$season.' ':'').($number?'E'.$number:'')));?></span><?php endif;?><?php if($runtime):?> <span><?php echo esc_html($runtime);?></span><?php endif;?></div><h1><?php the_title();?></h1><?php if($creator_id):?><p><a href="<?php echo esc_url(get_permalink($creator_id));?>"><?php echo esc_html(get_the_title($creator_id));?></a></p><?php endif;?><?php if($video):?><div class="nfinite-episode-player"><?php if($embed):?><button type="button" class="nfinite-tv__watch" data-video-embed="<?php echo esc_attr($embed);?>" data-video-creator-id="<?php echo esc_attr($creator_id);?>" data-video-object-type="episode" data-video-object-id="<?php echo esc_attr($episode_id);?>" data-video-surface="episode" data-video-title="<?php echo esc_attr(get_the_title());?>">▶ <?php esc_html_e('Watch Episode','nfinite-creators');?></button><?php else:?><a href="<?php echo esc_url($video);?>"><?php esc_html_e('Watch episode','nfinite-creators');?></a><?php endif;?></div><?php elseif($audio):?><audio class="nfinite-episode-audio" controls preload="metadata" src="<?php echo esc_url($audio);?>"></audio><?php endif;?><?php if(has_post_thumbnail()&&!$video):?><div class="nfinite-episode-art"><?php the_post_thumbnail('large');?></div><?php endif;?><div class="nfinite-episode-copy"><?php the_content();?></div><?php if($guests):?><p><strong><?php esc_html_e('Guests:','nfinite-creators');?></strong> <?php echo esc_html(implode(', ',array_filter(array_map('get_the_title',array_map('absint',$guests)))));?></p><?php endif;?></article></main>
<?php get_footer(); ?>
